import { validateField } from './validateField';

import type { FieldValidationResult, ValidationRule, Validator } from './types';

/**
 * Creates a reusable validator function from validation rules.
 *
 * This is useful for creating named validators that can be reused
 * across multiple forms or fields.
 *
 * **Key Features**:
 * - Reusable validator functions
 * - Type-safe
 * - Async support
 * - Composable validators
 *
 * @param rules - Array of validation rules
 * @returns Validator function
 *
 * @example
 * ```tsx
 * // Create reusable email validator
 * const validateEmail = createValidator<string>([
 *   {
 *     validate: (v) => v.length > 0,
 *     message: 'Email is required'
 *   },
 *   {
 *     validate: (v) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v),
 *     message: 'Email is invalid'
 *   }
 * ]);
 *
 * // Use in multiple places
 * const result1 = await validateEmail('john@example.com');
 * const result2 = await validateEmail('invalid');
 * ```
 *
 * @example
 * ```tsx
 * // Create password validator
 * const validatePassword = createValidator<string>([
 *   {
 *     validate: (v) => v.length >= 8,
 *     message: 'Password must be at least 8 characters'
 *   },
 *   {
 *     validate: (v) => /[A-Z]/.test(v),
 *     message: 'Password must contain uppercase letter'
 *   },
 *   {
 *     validate: (v) => /[0-9]/.test(v),
 *     message: 'Password must contain number'
 *   }
 * ]);
 *
 * const result = await validatePassword('Secure123');
 * // { valid: true }
 * ```
 */
export function createValidator<T = unknown>(rules: ValidationRule<T>[]): Validator<T> {
  return async (value: T): Promise<FieldValidationResult> => {
    return validateField(value, rules);
  };
}

import type { FormValidationResult } from './types';

/**
 * Extracts the error message for a specific field from form validation result.
 *
 * Helper function for getting field errors from form validation results.
 * Returns undefined if no error exists for the field.
 *
 * **Key Features**:
 * - Type-safe field access
 * - Undefined if no error
 * - Simple API
 *
 * @param result - Form validation result
 * @param fieldName - Name of the field
 * @returns Error message or undefined
 *
 * @example
 * ```tsx
 * const result = await validateForm(data, schema);
 * // { valid: false, errors: { email: 'Email is required', password: 'Password too short' } }
 *
 * const emailError = getFieldError(result, 'email');
 * // 'Email is required'
 *
 * const nameError = getFieldError(result, 'name');
 * // undefined
 * ```
 *
 * @example
 * ```tsx
 * // In a React component
 * function LoginForm() {
 *   const [errors, setErrors] = useState<FormValidationResult | null>(null);
 *
 *   const handleSubmit = async (data: LoginFormData) => {
 *     const result = await validateForm(data, schema);
 *     if (!result.valid) {
 *       setErrors(result);
 *       return;
 *     }
 *     // Submit form...
 *   };
 *
 *   return (
 *     <form onSubmit={handleSubmit}>
 *       <input name="email" />
 *       {errors && <span>{getFieldError(errors, 'email')}</span>}
 *     </form>
 *   );
 * }
 * ```
 */
export function getFieldError(result: FormValidationResult, fieldName: string): string | undefined {
  // eslint-disable-next-line security/detect-object-injection
  return result.errors[fieldName];
}

export { parseFormData } from './parseFormData';
export { serializeForm } from './serializeForm';

export { createValidator } from './createValidator';
export { getFieldError } from './getFieldError';
export { validateField } from './validateField';
export { validateForm, type ValidationSchema } from './validateForm';

export { isFormDirty } from './isFormDirty';
export { isFormValid } from './isFormValid';
export { resetForm } from './resetForm';

export { submitForm, type SubmitFormOptions, type SubmitFormResult } from './submitForm';

export type {
  FieldValidationResult,
  FormData,
  FormFieldValue,
  FormValidationResult,
  ValidationRule,
  Validator,
} from './types';

/**
 * Checks if form data has changed from initial values.
 *
 * Performs deep equality comparison to detect changes.
 * Useful for "unsaved changes" warnings.
 *
 * **Key Features**:
 * - Deep equality comparison
 * - Nested object support
 * - Array support
 * - Type-safe
 *
 * @param current - Current form data
 * @param initial - Initial form data
 * @returns True if data has changed
 *
 * @example
 * ```tsx
 * const initial = { name: 'John', email: 'john@example.com' };
 * const current = { name: 'Jane', email: 'john@example.com' };
 *
 * const isDirty = isFormDirty(current, initial);
 * // true
 * ```
 *
 * @example
 * ```tsx
 * // With nested objects
 * const initial = {
 *   user: { name: 'John', age: 30 },
 *   tags: ['react']
 * };
 * const current = {
 *   user: { name: 'John', age: 31 },
 *   tags: ['react']
 * };
 *
 * const isDirty = isFormDirty(current, initial);
 * // true (age changed)
 * ```
 *
 * @example
 * ```tsx
 * // In a component with unsaved changes warning
 * function EditForm({ initialData }: Props) {
 *   const [data, setData] = useState(initialData);
 *   const isDirty = isFormDirty(data, initialData);
 *
 *   useEffect(() => {
 *     const handleBeforeUnload = (e: BeforeUnloadEvent) => {
 *       if (isDirty) {
 *         e.preventDefault();
 *         e.returnValue = '';
 *       }
 *     };
 *
 *     window.addEventListener('beforeunload', handleBeforeUnload);
 *     return () => window.removeEventListener('beforeunload', handleBeforeUnload);
 *   }, [isDirty]);
 *
 *   return <form>...</form>;
 * }
 * ```
 */
export function isFormDirty(
  current: Record<string, unknown>,
  initial: Record<string, unknown>
): boolean {
  // Quick reference check
  if (current === initial) {
    return false;
  }

  // Check if keys are different
  const currentKeys = Object.keys(current);
  const initialKeys = Object.keys(initial);
  const initialEntries = new Map<string, unknown>(Object.entries(initial));

  if (currentKeys.length !== initialKeys.length) {
    return true;
  }

  // Deep comparison
  for (const [key, currentValue] of Object.entries(current)) {
    if (!initialEntries.has(key)) {
      return true;
    }
    const initialValue = initialEntries.get(key);

    // Check if both are objects (but not null, File, or Array)
    if (
      currentValue &&
      initialValue &&
      typeof currentValue === 'object' &&
      typeof initialValue === 'object' &&
      !(currentValue instanceof File) &&
      !(initialValue instanceof File) &&
      !Array.isArray(currentValue) &&
      !Array.isArray(initialValue)
    ) {
      if (
        isFormDirty(
          currentValue as Record<string, unknown>,
          initialValue as Record<string, unknown>
        )
      ) {
        return true;
      }
      continue;
    }

    // Check arrays
    if (Array.isArray(currentValue) && Array.isArray(initialValue)) {
      if (currentValue.length !== initialValue.length) {
        return true;
      }

      const initialIterator = initialValue[Symbol.iterator]();
      for (const currentItem of currentValue) {
        const { value: initialItem, done } = initialIterator.next();
        if (done || currentItem !== initialItem) {
          return true;
        }
      }
      continue;
    }

    // Primitive comparison
    if (currentValue !== initialValue) {
      return true;
    }
  }

  return false;
}

import type { FormValidationResult } from './types';

/**
 * Checks if a form validation result indicates a valid form.
 *
 * Simple helper to check if form has no validation errors.
 * Useful for enabling/disabling submit buttons.
 *
 * **Key Features**:
 * - Simple boolean check
 * - Type-safe
 * - Convenient API
 *
 * @param result - Form validation result
 * @returns True if form is valid (no errors)
 *
 * @example
 * ```tsx
 * const result = await validateForm(data, schema);
 *
 * if (isFormValid(result)) {
 *   // Submit form
 *   await submitForm(data);
 * } else {
 *   // Show errors
 *   setErrors(result.errors);
 * }
 * ```
 *
 * @example
 * ```tsx
 * // In a React component
 * function LoginForm() {
 *   const [validationResult, setValidationResult] = useState<FormValidationResult | null>(null);
 *
 *   const handleSubmit = async (data: LoginFormData) => {
 *     const result = await validateForm(data, schema);
 *     setValidationResult(result);
 *
 *     if (isFormValid(result)) {
 *       await api.login(data);
 *     }
 *   };
 *
 *   return (
 *     // Form with submit button disabled based on validation
 *     // Button is disabled if validation failed
 *   );
 * }
 * ```
 */
export function isFormValid(result: FormValidationResult): boolean {
  return result.valid;
}

/**
 * Converts FormData to a plain JavaScript object.
 *
 * Supports nested objects using dot notation (e.g., "user.name")
 * and arrays using bracket notation (e.g., "tags[0]").
 *
 * **Key Features**:
 * - Nested object support (dot notation)
 * - Array support (bracket notation)
 * - Multiple values for same key (converted to array)
 * - File upload handling
 * - Type-safe output
 * - **Security**: Guards against prototype pollution (rejects dangerous keys)
 *
 * @param formData - FormData instance to parse
 * @returns Plain object with nested structure
 *
 * @example
 * ```tsx
 * const formData = new FormData();
 * formData.append('name', 'John');
 * formData.append('email', 'john@example.com');
 * formData.append('user.age', '30');
 * formData.append('tags[0]', 'react');
 * formData.append('tags[1]', 'typescript');
 *
 * const data = parseFormData(formData);
 * // {
 * //   name: 'John',
 * //   email: 'john@example.com',
 * //   user: { age: '30' },
 * //   tags: ['react', 'typescript']
 * // }
 * ```
 *
 * @example
 * ```tsx
 * // With file uploads
 * const formData = new FormData();
 * formData.append('avatar', fileInput.files[0]);
 * formData.append('name', 'Jane');
 *
 * const data = parseFormData(formData);
 * // { avatar: File, name: 'Jane' }
 * ```
 */

/**
 * Set of keys that could be used for prototype pollution attacks.
 * These are always rejected when parsing FormData.
 */
const DANGEROUS_KEYS = new Set([
  '__proto__',
  'constructor',
  'prototype',
  '__defineGetter__',
  '__defineSetter__',
  '__lookupGetter__',
  '__lookupSetter__',
]);

// Only allow alphanumeric keys with common separators
const SAFE_KEY_PATTERN = /^[a-zA-Z0-9_.[\]-]+$/;

/**
 * Check if a key or any of its parts is dangerous (prototype pollution risk)
 */
function isDangerousKey(key: string): boolean {
  // Check if the full key matches
  if (DANGEROUS_KEYS.has(key)) {
    return true;
  }

  // Check array notation base key
  const arrayMatch = key.match(/^(.+)\[\d+\]$/);
  if (arrayMatch?.[1] && DANGEROUS_KEYS.has(arrayMatch[1])) {
    return true;
  }

  // Check each part of dot-notation keys
  if (key.includes('.')) {
    const parts = key.split('.');
    for (const part of parts) {
      if (DANGEROUS_KEYS.has(part)) {
        return true;
      }
    }
  }

  return false;
}

function createSafeObject(): Record<string, unknown> {
  // Null-prototype object to avoid prototype pollution and inherited props
  return Object.create(null) as Record<string, unknown>;
}

function isSafeKey(key: string): boolean {
  return SAFE_KEY_PATTERN.test(key) && !DANGEROUS_KEYS.has(key);
}

function getProperty<T = unknown>(obj: Record<string, unknown>, key: string): T | undefined {
  if (!isSafeKey(key)) {
    return undefined;
  }
  return Reflect.get(obj, key) as T | undefined;
}

function setProperty(obj: Record<string, unknown>, key: string, value: unknown): void {
  if (!isSafeKey(key)) {
    return;
  }
  Reflect.set(obj, key, value);
}

export function parseFormData(formData: FormData): Record<string, unknown> {
  const result: Record<string, unknown> = createSafeObject();

  formData.forEach((value, key) => {
    if (!isSafeKey(key) || isDangerousKey(key)) {
      if (process.env['NODE_ENV'] !== 'production') {
        console.warn(
          `[parseFormData] Skipping dangerous key "${key}" (prototype pollution protection)`
        );
      }
      return;
    }

    // Handle array notation: key[index]
    const arrayMatch = key.match(/^(.+)\[(\d+)\]$/);
    if (arrayMatch) {
      const arrayKey = arrayMatch[1];
      const index = arrayMatch[2];
      if (!arrayKey || !index || !isSafeKey(arrayKey)) {
        return;
      }

      const existing = getProperty<unknown[]>(result, arrayKey);
      const arr = Array.isArray(existing) ? existing : [];
      setProperty(result, arrayKey, arr);
      arr[Number.parseInt(index, 10)] = value;
      return;
    }

    // Handle nested object notation: key.subkey
    if (key.includes('.')) {
      const parts = key.split('.').filter((part) => part && isSafeKey(part));
      if (parts.length === 0) {
        return;
      }
      let current = result;

      for (let i = 0; i < parts.length - 1; i++) {
        const part = parts[i];
        if (typeof part !== 'string' || part.length === 0 || !isSafeKey(part)) {
          continue;
        }

        const existing = getProperty<Record<string, unknown>>(current, part);
        if (!existing || typeof existing !== 'object') {
          setProperty(current, part, createSafeObject());
        }
        current = getProperty<Record<string, unknown>>(current, part) ?? createSafeObject();
      }

      const lastPart = parts[parts.length - 1];
      if (typeof lastPart !== 'string' || lastPart.length === 0) {
        return;
      }
      if (isSafeKey(lastPart)) {
        setProperty(current, lastPart, value);
      }
      return;
    }

    // Handle multiple values for same key
    if (key in result) {
      const existing = getProperty<unknown>(result, key);
      if (Array.isArray(existing)) {
        existing.push(value);
      } else {
        setProperty(result, key, [existing, value]);
      }
      return;
    }

    // Simple key-value
    setProperty(result, key, value);
  });

  return result;
}

/**
 * Resets form data to initial values.
 *
 * Creates a deep clone of initial values to avoid mutation issues.
 * Useful for "Reset" buttons or canceling edits.
 *
 * **Key Features**:
 * - Deep clone (no mutations)
 * - Nested object support
 * - Array support
 * - Type-safe
 *
 * @param initial - Initial form values
 * @returns New object with initial values (deep cloned)
 *
 * @example
 * ```tsx
 * const initialData = { name: 'John', email: 'john@example.com' };
 * const currentData = { name: 'Jane', email: 'jane@example.com' };
 *
 * const reset = resetForm(initialData);
 * // { name: 'John', email: 'john@example.com' }
 * // (new object, not same reference as initialData)
 * ```
 *
 * @example
 * ```tsx
 * // In a React component
 * function EditProfileForm({ user }: Props) {
 *   const [data, setData] = useState(user);
 *
 *   const handleReset = () => {
 *     setData(resetForm(user));
 *   };
 *
 *   return (
 *     <form>
 *       <input
 *         value={data.name}
 *         onChange={(e) => setData({ ...data, name: e.target.value })}
 *       />
 *       <button type="button" onClick={handleReset}>
 *         Reset
 *       </button>
 *     </form>
 *   );
 * }
 * ```
 */
export function resetForm<T extends Record<string, unknown>>(initial: T): T {
  // Deep clone to avoid mutations
  return JSON.parse(JSON.stringify(initial)) as T;
}

/**
 * Serializes a form data object to URL-encoded string.
 *
 * Useful for GET requests, URL query parameters, or URL hash state.
 * Handles nested objects and arrays with standard encoding.
 *
 * **Key Features**:
 * - Nested object serialization (dot notation)
 * - Array serialization (bracket notation)
 * - URL encoding
 * - Null/undefined filtering
 * - Type-safe input
 *
 * @param data - Object to serialize
 * @param options - Serialization options
 * @returns URL-encoded query string (without leading "?")
 *
 * @example
 * ```tsx
 * const data = {
 *   name: 'John Doe',
 *   age: 30,
 *   tags: ['react', 'typescript'],
 *   user: { role: 'admin' }
 * };
 *
 * const query = serializeForm(data);
 * // "name=John%20Doe&age=30&tags%5B0%5D=react&tags%5B1%5D=typescript&user.role=admin"
 * ```
 *
 * @example
 * ```tsx
 * // With array indices option
 * const data = { tags: ['a', 'b', 'c'] };
 *
 * serializeForm(data, { arrayFormat: 'brackets' });
 * // "tags[]=a&tags[]=b&tags[]=c"
 *
 * serializeForm(data, { arrayFormat: 'repeat' });
 * // "tags=a&tags=b&tags=c"
 * ```
 */
export function serializeForm(
  data: Record<string, unknown>,
  options: {
    arrayFormat?: 'indices' | 'brackets' | 'repeat';
  } = {}
): string {
  const { arrayFormat = 'indices' } = options;
  const params: string[] = [];

  function serialize(obj: Record<string, unknown>, prefix = ''): void {
    for (const [key, value] of Object.entries(obj)) {
      // Skip null/undefined
      if (value === null || value === undefined) {
        continue;
      }

      const fullKey = prefix ? `${prefix}.${key}` : key;

      // Handle arrays
      if (Array.isArray(value)) {
        for (let i = 0; i < value.length; i++) {
          // eslint-disable-next-line security/detect-object-injection
          const item = value[i];
          if (item === null || item === undefined) {
            continue;
          }

          let arrayKey: string;
          if (arrayFormat === 'indices') {
            arrayKey = `${fullKey}[${i}]`;
          } else if (arrayFormat === 'brackets') {
            arrayKey = `${fullKey}[]`;
          } else {
            arrayKey = fullKey;
          }

          params.push(`${encodeURIComponent(arrayKey)}=${encodeURIComponent(String(item))}`);
        }
        continue;
      }

      // Handle nested objects
      if (typeof value === 'object' && !(value instanceof File)) {
        serialize(value as Record<string, unknown>, fullKey);
        continue;
      }

      // Handle primitive values
      params.push(`${encodeURIComponent(fullKey)}=${encodeURIComponent(String(value))}`);
    }
  }

  serialize(data);
  return params.join('&');
}

import { validateForm, type ValidationSchema } from './validateForm';

import type { FormValidationResult } from './types';

/**
 * Options for form submission.
 */
export interface SubmitFormOptions<T extends Record<string, unknown>> {
  /** Validation schema (optional) */
  schema?: ValidationSchema<T>;
  /** Callback for successful submission */
  onSuccess?: (data: T) => void | Promise<void>;
  /** Callback for validation errors */
  onError?: (result: FormValidationResult) => void;
  /** Transform data before submission */
  transform?: (data: T) => T | Promise<T>;
}

/**
 * Result of form submission.
 */
export interface SubmitFormResult {
  /** Whether submission was successful */
  success: boolean;
  /** Validation result if validation failed */
  validation?: FormValidationResult;
  /** Error if submission callback threw */
  error?: Error;
}

/**
 * Validates and submits form data.
 *
 * Handles the complete form submission flow:
 * 1. Validate data (if schema provided)
 * 2. Transform data (if transform provided)
 * 3. Call success callback
 * 4. Handle errors
 *
 * **Key Features**:
 * - Integrated validation
 * - Data transformation
 * - Success/error callbacks
 * - Type-safe
 * - Async support
 *
 * @param data - Form data to submit
 * @param options - Submission options
 * @returns Submission result
 *
 * @example
 * ```tsx
 * interface LoginForm {
 *   email: string;
 *   password: string;
 * }
 *
 * const schema: ValidationSchema<LoginForm> = {
 *   email: [
 *     { validate: (v) => v.length > 0, message: 'Email required' },
 *     { validate: (v) => v.includes('@'), message: 'Email invalid' }
 *   ],
 *   password: [
 *     { validate: (v) => v.length >= 8, message: 'Password too short' }
 *   ]
 * };
 *
 * const result = await submitForm(formData, {
 *   schema,
 *   onSuccess: async (data) => {
 *     await api.login(data);
 *     navigate('/dashboard');
 *   },
 *   onError: (validation) => {
 *     setErrors(validation.errors);
 *   }
 * });
 *
 * if (result.success) {
 *   console.log('Login successful!');
 * }
 * ```
 *
 * @example
 * ```tsx
 * // With data transformation
 * const result = await submitForm(formData, {
 *   schema,
 *   transform: (data) => ({
 *     ...data,
 *     email: data.email.toLowerCase().trim()
 *   }),
 *   onSuccess: async (data) => {
 *     await api.createUser(data);
 *   }
 * });
 * ```
 */
export async function submitForm<T extends Record<string, unknown>>(
  data: T,
  options: SubmitFormOptions<T> = {}
): Promise<SubmitFormResult> {
  const { schema, onSuccess, onError, transform } = options;

  try {
    // Validate if schema provided
    if (schema) {
      const validation = await validateForm(data, schema);

      if (!validation.valid) {
        if (onError) {
          onError(validation);
        }
        return {
          success: false,
          validation,
        };
      }
    }

    // Transform data if transform provided
    let finalData = data;
    if (transform) {
      finalData = await transform(data);
    }

    // Call success callback
    if (onSuccess) {
      await onSuccess(finalData);
    }

    return { success: true };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error : new Error(String(error)),
    };
  }
}

/**
 * Validation rule for a form field.
 */
export interface ValidationRule<T = unknown> {
  /** Validation function that returns true if valid */
  validate: (value: T) => boolean | Promise<boolean>;
  /** Error message to display when validation fails */
  message: string;
}

/**
 * Validation result for a field.
 */
export interface FieldValidationResult {
  /** Whether the field is valid */
  valid: boolean;
  /** Error message if invalid */
  error?: string;
}

/**
 * Validation result for an entire form.
 */
export interface FormValidationResult {
  /** Whether the form is valid */
  valid: boolean;
  /** Map of field names to error messages */
  errors: Record<string, string>;
}

/**
 * Validator function type.
 */
export type Validator<T = unknown> = (
  value: T
) => FieldValidationResult | Promise<FieldValidationResult>;

/**
 * Form field value type.
 */
export type FormFieldValue = string | number | boolean | File | null | undefined;

/**
 * Form data type (nested objects and arrays supported).
 */
export interface FormDataMap {
  [key: string]: FormDataValue;
}

export type FormDataValue = FormFieldValue | FormFieldValue[] | FormDataMap;

export type FormData = FormDataMap;

import type { FieldValidationResult, ValidationRule } from './types';

/**
 * Validates a single form field against validation rules.
 *
 * Runs all validation rules and returns the first error encountered.
 * Supports both synchronous and asynchronous validators.
 *
 * **Key Features**:
 * - Multiple validation rules per field
 * - Async validation support
 * - Short-circuit on first error
 * - Type-safe validators
 * - **Error handling**: Gracefully handles validators that throw exceptions
 *
 * @param value - Field value to validate
 * @param rules - Array of validation rules
 * @returns Validation result with error message if invalid
 *
 * @example
 * ```tsx
 * const emailRules: ValidationRule<string>[] = [
 *   {
 *     validate: (v) => v.length > 0,
 *     message: 'Email is required'
 *   },
 *   {
 *     validate: (v) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v),
 *     message: 'Email is invalid'
 *   }
 * ];
 *
 * const result = await validateField('john@example.com', emailRules);
 * // { valid: true }
 *
 * const result2 = await validateField('invalid', emailRules);
 * // { valid: false, error: 'Email is invalid' }
 * ```
 *
 * @example
 * ```tsx
 * // With async validation
 * const usernameRules: ValidationRule<string>[] = [
 *   {
 *     validate: (v) => v.length >= 3,
 *     message: 'Username must be at least 3 characters'
 *   },
 *   {
 *     validate: async (v) => {
 *       const available = await checkUsernameAvailable(v);
 *       return available;
 *     },
 *     message: 'Username is already taken'
 *   }
 * ];
 *
 * const result = await validateField('john', usernameRules);
 * ```
 */
export async function validateField<T = unknown>(
  value: T,
  rules: ValidationRule<T>[]
): Promise<FieldValidationResult> {
  for (const rule of rules) {
    try {
      const isValid = await rule.validate(value);
      if (!isValid) {
        return {
          valid: false,
          error: rule.message,
        };
      }
    } catch (error) {
      // Handle validators that throw exceptions
      // Treat as validation failure and use the rule's message
      if (process.env['NODE_ENV'] !== 'production') {
        console.warn(
          `[validateField] Validator threw an exception: ${error instanceof Error ? error.message : String(error)}`
        );
      }
      return {
        valid: false,
        error: rule.message,
      };
    }
  }

  return { valid: true };
}

import { validateField } from './validateField';

import type { FormValidationResult, ValidationRule } from './types';

/**
 * Schema for form validation.
 */
export type ValidationSchema<T extends Record<string, unknown>> = {
  [K in keyof T]?: ValidationRule<T[K]>[];
};

/**
 * Validates an entire form against a validation schema.
 *
 * Runs all field validators and collects errors.
 * Supports nested objects and async validators.
 *
 * **Key Features**:
 * - Schema-based validation
 * - Async validation support
 * - Nested object validation
 * - Collects all errors (not short-circuit)
 * - Type-safe schema
 *
 * @param data - Form data to validate
 * @param schema - Validation schema mapping field names to rules
 * @returns Validation result with all field errors
 *
 * @example
 * ```tsx
 * interface LoginForm {
 *   email: string;
 *   password: string;
 * }
 *
 * const schema: ValidationSchema<LoginForm> = {
 *   email: [
 *     { validate: (v) => v.length > 0, message: 'Email required' },
 *     { validate: (v) => v.includes('@'), message: 'Email invalid' }
 *   ],
 *   password: [
 *     { validate: (v) => v.length >= 8, message: 'Password must be 8+ chars' }
 *   ]
 * };
 *
 * const result = await validateForm(
 *   { email: 'john@example.com', password: 'short' },
 *   schema
 * );
 * // {
 * //   valid: false,
 * //   errors: { password: 'Password must be 8+ chars' }
 * // }
 * ```
 *
 * @example
 * ```tsx
 * // All fields valid
 * const result = await validateForm(
 *   { email: 'john@example.com', password: 'secure123' },
 *   schema
 * );
 * // { valid: true, errors: {} }
 * ```
 */
export async function validateForm<T extends Record<string, unknown>>(
  data: T,
  schema: ValidationSchema<T>
): Promise<FormValidationResult> {
  const errors: Record<string, string> = {};

  // Validate all fields in parallel
  const validations = Object.entries(schema).map(async ([field, rules]) => {
    if (!rules) {
      return;
    }

    // eslint-disable-next-line security/detect-object-injection
    const value = data[field];
    const result = await validateField(value, rules);

    if (!result.valid && result.error) {
      // eslint-disable-next-line security/detect-object-injection
      errors[field] = result.error;
    }
  });

  await Promise.all(validations);

  return {
    valid: Object.keys(errors).length === 0,
    errors,
  };
}
